/*
 * Traduz o payload MESSAGES_UPSERT da Evolution para o formato da
 * ingestão do motor, e DESCARTA o que não interessa.
 *
 * LGPD: `participant` e `pushName` (telefone e nome de quem postou)
 * existem no payload e são deliberadamente ignorados. Só o conteúdo
 * da oferta atravessa este nó. O motor ainda faz uma segunda limpeza
 * do lado dele — camada dupla, de propósito.
 */
const saida = [];

for (const item of $input.all()) {
  const p = item.json?.body ?? item.json ?? {};
  if (p.event !== 'messages.upsert') continue;

  const d = p.data ?? {};
  const key = d.key ?? {};
  if (key.fromMe) continue;                       // não é oferta de concorrente

  const jid = key.remoteJid ?? '';
  if (!jid.endsWith('@g.us')) continue;           // só grupo, nunca conversa privada

  const m = d.message ?? {};
  const texto =
    m.conversation ??
    m.extendedTextMessage?.text ??
    m.imageMessage?.caption ??
    m.videoMessage?.caption ??
    '';
  if (!texto.trim()) continue;                    // figurinha, áudio, entrou/saiu

  saida.push({
    json: {
      groupJid: jid,
      text: texto,
      // A Evolution manda em SEGUNDOS. O motor aceita os dois e normaliza.
      postedAt: d.messageTimestamp ?? null,
      hasImage: m.imageMessage != null,
      instanceRef: p.instance ?? null,
    },
  });
}

return saida;
